// Recovery power index — record JAH-GGNS-MASSAGEGUN-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"amplitude_mm": 16, "rpm": 3200, "noise_db": 60, "price_usd": 400};
var value = (m.amplitude_mm*m.rpm/m.noise_db/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-MASSAGEGUN-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-MASSAGEGUN-000001|' + value.toFixed(2) + ' recovery index');

